function slugify(string $value): string
{
    $slug = strtolower((string) preg_replace('/[^a-zA-Z0-9]+/', '-', $value));
    $slug = trim($slug, '-');
    return $slug === '' ? 'session' : $slug;
}

function ensureDirectory(string $directory): void
{
    if (is_dir($directory)) {
        return;
    }
    if (!mkdir($directory, 0o775, true) && !is_dir($directory)) {
        throw new RuntimeException("Unable to create directory: {$directory}");
    }
}

function writeJsonFile(string $path, array $payload): void
{
    ensureDirectory(dirname($path));
    file_put_contents($path, json_encode($payload, JSON_PRETTY_PRINT | JSON_UNESCAPED_SLASHES | JSON_THROW_ON_ERROR).PHP_EOL);
}

function copyFileOrFail(string $src, string $dest): void
{
    ensureDirectory(dirname($dest));
    if (!copy($src, $dest)) {
        throw new RuntimeException("copy failed: {$src} -> {$dest}");
    }
}

function fileContains(string $path, string $needle): bool
{
    if (!is_file($path)) {
        return false;
    }
    $fh = fopen($path, 'r');
    if ($fh === false) {
        return false;
    }
    while (!feof($fh)) {
        $chunk = fread($fh, 8192);
        if ($chunk !== false && str_contains($chunk, $needle)) {
            fclose($fh);
            return true;
        }
    }
    fclose($fh);
    return false;
}

/** @return list<string> */
function findFiles(string $root, string $glob): array
{
    $files = [];
    if (!is_dir($root)) {
        return $files;
    }
    $it = new RecursiveIteratorIterator(
        new RecursiveDirectoryIterator($root, RecursiveDirectoryIterator::SKIP_DOTS),
        RecursiveIteratorIterator::SELF_FIRST,
    );
    foreach ($it as $entry) {
        if ($entry->isFile() && fnmatch($glob, $entry->getFilename())) {
            $files[] = $entry->getPathname();
        }
    }
    return $files;
}

function captureCodexExact(string $home, string $cwd, int $soloProcessId, string $markerNeedle, mixed $startedAt): array
{
    $root = "{$home}/.codex/sessions";
    $candidates = [];
    $checked = [];
    $rollouts = findFiles($root, '*.jsonl');

    foreach ($rollouts as $file) {
        $checked[] = $file;
        if (! codexFileHasScopedMarker($file, $markerNeedle)) {
            continue;
        }
        $candidates[] = $file;
    }

    if ($candidates === []) {
        return [
            'status' => 'missing',
            'reason' => 'exact_marker_not_found',
            'checked' => array_slice($checked, 0, 20),
        ];
    }

    $chosen = $candidates[0];
    $disambiguationBasis = null;
    $timestampCorroboration = null;

    if (count($candidates) > 1) {
        $normalizedCwd = normalizeCodexCwd($cwd);
        $survivors = [];

        foreach ($candidates as $candidate) {
            $context = codexCandidateContext($candidate);

            if ($context['normalized_cwd'] !== $normalizedCwd) {
                continue;
            }

            if ($context['primary_solo_process_id'] !== $soloProcessId) {
                continue;
            }

            $survivors[] = [
                'path' => $candidate,
                'timestamp' => $context['timestamp'],
            ];
        }

        if (count($survivors) !== 1) {
            return [
                'status' => 'ambiguous',
                'reason' => 'ambiguous_duplicate_markers',
                'checked' => array_slice($checked, 0, 20),
            ];
        }

        $chosen = $survivors[0]['path'];
        $timestampCorroboration = codexTimestampCorroboration($survivors[0]['timestamp'], $startedAt);
        $disambiguationBasis = sprintf(
            'provider=codex; normalized_cwd=exact; primary_solo_process_id=%d; timestamp_corroboration=%s',
            $soloProcessId,
            $timestampCorroboration,
        );
    }

    // Parse minimal usage + messages from the rollout (reuse light logic)
    $messages = [];
    $usage = ['input_tokens' => 0, 'output_tokens' => 0, 'total_tokens' => 0];
    foreach (jsonl($chosen) as $row) {
        $type = $row['type'] ?? '';
        if ($type === 'response_item' && isset($row['payload']['content'])) {
            foreach ($row['payload']['content'] as $c) {
                if (isset($c['text'])) {
                    $messages[] = ['role' => $row['payload']['role'] ?? 'unknown', 'content' => $c['text']];
                }
            }
        }
        if ($type === 'event_msg' && ($row['payload']['type'] ?? '') === 'token_count') {
            $u = $row['payload']['info']['total_token_usage'] ?? [];
            $usage['input_tokens'] = (int) ($u['input_tokens'] ?? 0);
            $usage['output_tokens'] = (int) ($u['output_tokens'] ?? 0);
            $usage['reasoning_tokens'] = (int) ($u['reasoning_output_tokens'] ?? 0);
            $usage['total_tokens'] = (int) ($u['total_tokens'] ?? 0);
        }
    }

    $messagesJsonl = implode("\n", array_map(fn($m) => json_encode(['role' => $m['role'], 'content' => $m['content']], JSON_UNESCAPED_SLASHES), $messages));

    $result = [
        'status' => 'ok',
        'source' => 'codex_exact_marker',
        'artifact' => $chosen,
        'usage' => $usage,
        'messages_jsonl' => $messagesJsonl,
        'raw_files' => [['path' => $chosen, 'archive_name' => basename($chosen)]],
    ];

    if ($disambiguationBasis !== null) {
        $result['disambiguation_basis'] = $disambiguationBasis;
        $result['timestamp_corroboration'] = $timestampCorroboration;
    }

    return $result;
}

/**
 * @return array{
 *     normalized_cwd: ?string,
 *     primary_solo_process_id: ?int,
 *     timestamp: mixed,
 * }
 */
function codexCandidateContext(string $path): array
{
    $candidateCwd = null;
    $timestamp = null;
    $baseInstructionsIdentity = null;
    $firstUserIdentity = null;
    $firstUserMessageSeen = false;

    foreach (jsonl($path) as $row) {
        if (($row['type'] ?? null) === 'session_meta') {
            $payload = $row['payload'] ?? [];

            if ($candidateCwd === null && is_string($payload['cwd'] ?? null)) {
                $candidateCwd = $payload['cwd'];
            }

            if ($timestamp === null && array_key_exists('timestamp', $payload)) {
                $timestamp = $payload['timestamp'];
            }

            if ($baseInstructionsIdentity === null) {
                $base = $payload['base_instructions'] ?? '';
                $baseText = is_array($base) && isset($base['text'])
                    ? (string) $base['text']
                    : (is_string($base) ? $base : '');
                $baseInstructionsIdentity = soloProcessIdFromText($baseText);
            }

            continue;
        }

        if ($firstUserMessageSeen || ($row['type'] ?? null) !== 'response_item') {
            continue;
        }

        $payload = $row['payload'] ?? [];

        if (($payload['type'] ?? null) !== 'message' || ($payload['role'] ?? null) !== 'user') {
            continue;
        }

        $firstUserMessageSeen = true;
        $firstUserIdentity = soloProcessIdFromUserIdentityMarker(extractText($payload['content'] ?? ''));
    }

    return [
        'normalized_cwd' => normalizeCodexCwd($candidateCwd),
        'primary_solo_process_id' => $baseInstructionsIdentity ?? $firstUserIdentity,
        'timestamp' => $timestamp,
    ];
}

function soloProcessIdFromText(string $text): ?int
{
    if (preg_match('/Solo process ID:\s*(\d+)\b/', $text, $matches) !== 1) {
        return null;
    }

    return (int) $matches[1];
}

function soloProcessIdFromUserIdentityMarker(string $text): ?int
{
    if (preg_match('/(?:^|\R)\s*Solo process ID:\s*(\d+)\b/', $text, $matches) !== 1) {
        return null;
    }

    return (int) $matches[1];
}

function normalizeCodexCwd(?string $cwd): ?string
{
    if ($cwd === null || trim($cwd) === '') {
        return null;
    }

    $resolved = realpath($cwd);

    if ($resolved !== false) {
        return $resolved;
    }

    $isAbsolute = str_starts_with($cwd, '/');
    $segments = [];

    foreach (preg_split('~/+~', $cwd) ?: [] as $segment) {
        if ($segment === '' || $segment === '.') {
            continue;
        }

        if ($segment === '..') {
            if ($segments !== [] && end($segments) !== '..') {
                array_pop($segments);
            } elseif (! $isAbsolute) {
